with valid as (select *, case when level in ('L3', 'L2') then 'Tier 1' else 'Other' end as level_group, coalesce(email, 'N/A') as email_filled, coalesce(job_title, 'OTHER') as resolved_job_title from employees where hire_date > date '2023-06-26' and job_title is not null), remaining_keys as (select level, manager_id from valid intersect select level, manager_id from employees where is_remote = true), verified as (select s.* from valid s inner join remaining_keys k on s.level = k.level and s.manager_id = k.manager_id), metrics as (select *, dense_rank() over (partition by manager_id order by salary) as salary_dense_rank, avg(salary) over (partition by manager_id) as manager_id_avg_salary, dense_rank() over (order by salary) as salary_dense_rank_2 from verified), scored as (select *, sum(manager_id_avg_salary) over (partition by dept_id, job_title) as dept_id_sum_manager_id_avg_salary, round(salary / sum(salary) over (partition by level), 4) as salary_share, round(manager_id_avg_salary / sum(manager_id_avg_salary) over (partition by level), 4) as manager_id_avg_salary_share, rank() over (partition by manager_id order by manager_id_avg_salary) as manager_id_avg_salary_rank from metrics), enriched as (select src.*, d.dept_name, d.budget, d.location from scored src inner join departments d on src.dept_id = d.id), enriched_employees as (select s.*, e.full_name as employee_full_name, e.email as employee_email, e.job_title as employee_job_title from enriched s inner join employees e on s.manager_id = e.id), enriched_employees_2 as (select *, dense_rank() over (partition by dept_name order by salary_dense_rank) as salary_dense_rank_dense_rank, sum(budget) over (partition by level) as level_sum_budget from enriched_employees) select date_trunc('week', hire_date) as week_start, size(collect_set(job_title)) as num_job_titles, sort_array(collect_set(employee_job_title)) as employee_job_title_list from enriched_employees_2 group by date_trunc('week', hire_date);
